38	/// ycsb_token — Hybrid-Brücke: bestehende compile-time-WorkloadKind (YCSB A–F) → runtime-profile_by_name-Token.
39	/// Custom_*-Ops (WorkloadKind) haben in profile_by_name kein Mess-Lastprofil-Pendant → "" (3-Mengen-
40	/// Vereinheitlichung = offene Design-Folge, Ledger). "" ist zugleich profile_by_name's „überspringen"-Marker.
41	[[nodiscard]] constexpr std::string_view ycsb_token(cmd::WorkloadKind k) noexcept {
42	    switch (k) {
43	        case cmd::WorkloadKind::YCSB_A_Read50Write50: return "A";
44	        case cmd::WorkloadKind::YCSB_B_Read95Write5: return "B";
45	        case cmd::WorkloadKind::YCSB_C_ReadOnly: return "C";
46	        case cmd::WorkloadKind::YCSB_D_ReadLatest: return "D";
47	        case cmd::WorkloadKind::YCSB_E_Scan95: return "E";
48	        case cmd::WorkloadKind::YCSB_F_ReadModifyWrite: return "F";
49	        case cmd::WorkloadKind::Custom_HotKey:
50	        case cmd::WorkloadKind::Custom_RangeDelete:
51	        case cmd::WorkloadKind::Custom_BulkInsert: return ""; // offene 3-Mengen-Vereinheitlichung
52	    }
53	    return "";
54	}
