61	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_D_ReadLatest>,
62	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_E_Scan95>,
63	                std::integral_constant<cmd::WorkloadKind, cmd::WorkloadKind::YCSB_F_ReadModifyWrite>>;
