67	/// config_for — Hybrid: compile-time-WorkloadKind (YCSB A–F) → runtime-WorkloadConfig via profile_by_name
68	/// (bit-identisch delegiert, golden-neutral). seed/ops bleiben runtime (dynamische Achse).
69	[[nodiscard]] inline WorkloadConfig config_for(cmd::WorkloadKind k, std::uint64_t seed, std::size_t ops) {
70	    return profile_by_name(ycsb_token(k), seed, ops);
71	}
