34	/// ContainerType<G> -- G ist ein Container-TYP gdw. (1) seine Gattung die Container-Gattung ist
35	/// (Ebene-1-Aussen-Interface) UND (2) eine Bau-Bindung existiert (baubare Tier-Unterklasse). Die
36	/// SearchAlgorithm-Gattung erfuellt (1) NICHT und ist damit kein Container-Typ (self-proving unten).
37	template <cea::AnatomyGenus G>
38	concept ContainerType = (cea::gattung_of(G) == cea::AnatomyGattung::Container) && cexp::GenusBound<G>;
39	
40	/// type_list -- die Container-TYPEN als compile-time-Liste (Adapter/Set/Sequence/View). Jeder Eintrag ist
41	/// die AnatomyGenus-Tier-Unterklasse als integral_constant (mp11-iterierbar). Reihenfolge = Enum-Reihenfolge.
42	using type_list = mp::mp_list<std::integral_constant<cea::AnatomyGenus, cea::AnatomyGenus::Adapter>,
43	                              std::integral_constant<cea::AnatomyGenus, cea::AnatomyGenus::Set>,
44	                              std::integral_constant<cea::AnatomyGenus, cea::AnatomyGenus::Sequence>,
45	                              std::integral_constant<cea::AnatomyGenus, cea::AnatomyGenus::View>>;
46	
47	/// type_count -- Anzahl der Container-Genus-TYPEN (heute 4, Ebene 2). Weitere std-Container (linked list,
48	/// deque, array ...) werden als Ebene-3-Realisierungen UNTER den bestehenden Genus geplant (Option A,
49	/// empfohlen, type_count bleibt 4) ODER als eigener Genus (Option B, type_count-wachsend) -- Fork +
50	/// Empfehlung: docs/architecture/37_ap15_container_typen_sequence_plan.md (AP-15 Punkt 3).
51	inline constexpr std::size_t type_count = mp::mp_size<type_list>::value;
52	
53	/// type_traits<G> -- das generische comdare::container-Interface je Container-TYP. RE-EXPORTIERT die
54	/// bestehende GenusBindingTraits<G> (Achsen-Satz/Slot-Zahl/Komposition/Anatomie bleiben unveraendert je Typ).
55	template <cea::AnatomyGenus G>
56	    requires ContainerType<G>
57	struct type_traits {
58	    static constexpr cea::AnatomyGenus   genus      = G;
59	    static constexpr cea::AnatomyGattung gattung    = cea::AnatomyGattung::Container; // Ebene-1-Aussen-Interface
60	    static constexpr std::size_t         slot_count = cexp::GenusBindingTraits<G>::slot_count;
61	    static constexpr std::string_view    name       = cexp::GenusBindingTraits<G>::name;
62	
63	    /// Blatt-PermTuple -> reale Komposition (unveraendert je Typ; nur weitergereicht).
64	    template <class... T>
65	    using CompositionFor = typename cexp::GenusBindingTraits<G>::template CompositionFor<T...>;
66	    template <class Comp>
67	    using AnatomyFor = typename cexp::GenusBindingTraits<G>::template AnatomyFor<Comp>;
68	
69	    /// Der bisherige Achsen-Satz dieses Typs (exakt beibehalten).
70	    [[nodiscard]] static constexpr auto const& axis_names() noexcept {
71	        return cexp::GenusBindingTraits<G>::axis_names();
72	    }
73	};
