75	// ── Self-proving (compile-time; kein Raten) ─────────────────────────────────────────────────────
76	// (a) Alle 4 Tier-Unterklassen der Container-Gattung sind Container-TYPEN; SearchAlgorithm ist es NICHT.
77	static_assert(type_count == 4, "#29: Container-Typen heute = Adapter/Set/Sequence/View");
78	static_assert(ContainerType<cea::AnatomyGenus::Adapter>);
79	static_assert(ContainerType<cea::AnatomyGenus::Set>);
80	static_assert(ContainerType<cea::AnatomyGenus::Sequence>);
81	static_assert(ContainerType<cea::AnatomyGenus::View>);
82	static_assert(!ContainerType<cea::AnatomyGenus::SearchAlgorithm>,
83	              "#29: SearchAlgorithm ist eine EIGENE Gattung, kein Container-Typ");
84	// (b) "exakt die bisherigen Container-Achsen": jeder Typ behaelt seinen Slot-Satz (keine Vereinheitlichung).
85	static_assert(type_traits<cea::AnatomyGenus::Adapter>::slot_count == 13);
86	static_assert(type_traits<cea::AnatomyGenus::Set>::slot_count == 15);
87	static_assert(type_traits<cea::AnatomyGenus::Sequence>::slot_count == 11);
88	static_assert(type_traits<cea::AnatomyGenus::View>::slot_count == 7);
89	// (c) Gattungs-Konsistenz: alle Container-Typen tragen das Container-Aussen-Interface (Ebene 1).
90	static_assert(type_traits<cea::AnatomyGenus::Adapter>::gattung == cea::AnatomyGattung::Container);
91	static_assert(type_traits<cea::AnatomyGenus::View>::gattung == cea::AnatomyGattung::Container);
